contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Try three owner-only operations with provided amount and target; ensure pre-funded for sendMoney and withdraw amounts.
    function run(uint amount, address target) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        // observe before state
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        bool revertedWithdraw;
        bool revertedWithdrawAll;
        bool revertedSend;

        // Attempt withdraw
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedWithdraw = true;
        } else {
            revertedWithdraw = false;
        }

        // Attempt withdrawAll
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            revertedWithdrawAll = true;
        } else {
            revertedWithdrawAll = false;
        }

        // Attempt sendMoney
        c.sendMoney(target, amount); bool __rev2 = __ESBMC_reverted(); if (__rev2) {
            revertedSend = true;
        } else {
            revertedSend = false;
        }

        // observe after state
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        // If any of the calls reverted, then depositsCount and balance must remain exactly as before.
        // Otherwise (none reverted) we make no claim here about exact values.
        assert(
            revertedWithdraw || revertedWithdrawAll || revertedSend
            ? (afterDeposits == beforeDeposits && afterBalance == beforeBalance)
            : true
        );
    }

    receive() external payable {}
}

